program.compute:
pool = read('/input/options')
pool = sorted(pool, key=lambda row: row['id'])
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
artifact = read('/output/selection')
if artifact is None:
    write('/output/selection', result)
    artifact = result
state = status('report')
receipt_state = receipt('report')
if state == 'not_sent' and receipt_state != 'success':
    send('report', 'team', artifact)
if exists('/tmp/cache'):
    delete('/tmp/cache')

